package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_29_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        String version = "1.3.1";
        int expectedVersionInt = 131;

        // Call the method under test
        float actualVersionFloat = SystemUtils.toJavaVersionInt(version);

        // Check if the returned value is a float (which is incorrect)
        assertTrue("The version should be returned as an integer", actualVersionFloat % 1 != 0);

        // Check if the returned value matches the expected integer value
        assertEquals("The version should be converted to an integer", expectedVersionInt, (int) actualVersionFloat);
    }
}

